INSERT INTO study_questions (id, subject, year, category, question, options, correct_answer, difficulty, sort_order, hidden) VALUES ('mat-2023-mq-0026', 'math', 2023, 'objective', 'A statistical hypothesis can be', '[{"label": "A", "text": "null/exact."}, {"label": "B", "text": "null/simple."}, {"label": "C", "text": "simple/composite."}, {"label": "D", "text": "exact/composite."}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0027', 'math', 2023, 'objective', 'Four coins are tossed together. Determine the probability that they will show the same face.', '[{"label": "A", "text": "1/16"}, {"label": "B", "text": "1/8"}, {"label": "C", "text": "\u00bc"}, {"label": "D", "text": "\u00bd"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0028', 'math', 2023, 'objective', 'Given the table (insufficient data)', '[{"label": "A", "text": ""}, {"label": "B", "text": ""}, {"label": "C", "text": ""}, {"label": "D", "text": ""}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0029', 'math', 2023, 'objective', 'Evaluate the mean of the set of data 97,91,94,90,85', '[{"label": "A", "text": "91"}, {"label": "B", "text": "92"}, {"label": "C", "text": "94"}, {"label": "D", "text": "95"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0030', 'math', 2023, 'objective', 'If two fair dice are tossed, determine the probability that total score that shows up is 8.', '[{"label": "A", "text": "3/12"}, {"label": "B", "text": "5/36"}, {"label": "C", "text": "1/36"}, {"label": "D", "text": "19/36"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0031', 'math', 2023, 'objective', 'Determine the number of different arrangements of the letters of the word OGBOMOSO.', '[{"label": "A", "text": "2400"}, {"label": "B", "text": "1280"}, {"label": "C", "text": "1500"}, {"label": "D", "text": "1680"}]'::jsonb, 'D', 'medium', 0, false),('mat-2023-mq-0032', 'math', 2023, 'objective', 'Evaluate ∫₂³ x/(1+x²) dx.', '[{"label": "A", "text": "\u03c0/4"}, {"label": "B", "text": "2\u03c0/5"}, {"label": "C", "text": "\u03c0"}, {"label": "D", "text": "\u03c0/2"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0033', 'math', 2023, 'objective', 'If y = ln (x + 2ˣ), find dy/dx.', '[{"label": "A", "text": "(1+2\u02e3ln2)/(x+2\u02e3)"}, {"label": "B", "text": "(1\u20132\u02e3ln2)/(x+2\u02e3)"}, {"label": "C", "text": "(2\u02e3ln2\u20131)/(x+2\u02e3)"}, {"label": "D", "text": "2\u02e3/(x+2\u02e3)"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0034', 'math', 2023, 'objective', 'What is the derivative of y = cos²x + sin²x', '[{"label": "A", "text": "0"}, {"label": "B", "text": "1"}, {"label": "C", "text": "2sin2x"}, {"label": "D", "text": "-2cosx+2sinx"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0035', 'math', 2023, 'objective', 'Deduce the coefficient of variation of this population data: 7, 10, 11, 12', '[{"label": "A", "text": "1.87"}, {"label": "B", "text": "0.187"}, {"label": "C", "text": "3.5"}, {"label": "D", "text": "0.35"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0036', 'math', 2023, 'objective', 'What is the derivative of y = cos2x + sin2x', '[{"label": "A", "text": "0"}, {"label": "B", "text": "1"}, {"label": "C", "text": "2sin2x"}, {"label": "D", "text": "-2cosx + 2sinx"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0037', 'math', 2023, 'objective', 'Deduce the coefficient of variation of this population data: 7, 10, 11, 12', '[{"label": "A", "text": "1.87"}, {"label": "B", "text": "0.187"}, {"label": "C", "text": "3.5"}, {"label": "D", "text": "0.35"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0038', 'math', 2023, 'objective', 'A random distribution that measures rare events in space and time that has its mean and variance the same is expressed as', '[{"label": "A", "text": "Beta Distribution"}, {"label": "B", "text": "Gamma Distribution"}, {"label": "C", "text": "Hypergeometric Distribution"}, {"label": "D", "text": "Poisson Distribution"}]'::jsonb, 'D', 'medium', 0, false),('mat-2023-mq-0039', 'math', 2023, 'objective', 'Determine the number of complete permutations of the letters of the word MISSISSIPPI', '[{"label": "A", "text": "34650"}, {"label": "B", "text": "12967"}, {"label": "C", "text": "6750"}, {"label": "D", "text": "35550"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0040', 'math', 2023, 'objective', 'The sampling technique that does not involve the use of random sampling is identified as', '[{"label": "A", "text": "Quota."}, {"label": "B", "text": "Stratified."}, {"label": "C", "text": "Systematic"}, {"label": "D", "text": "Multi-stage."}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0041', 'math', 2023, 'objective', 'A loan N1000 is given at 15% for 8 months. Find the maturity of the loan.', '[{"label": "A", "text": "N1300"}, {"label": "B", "text": "N1100"}, {"label": "C", "text": "N1200"}, {"label": "D", "text": "N1050"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0042', 'math', 2023, 'objective', 'What is an amount established so that maturity value equals a specific amount at regular intervals?', '[{"label": "A", "text": "Annuity."}, {"label": "B", "text": "Sinking Fund."}, {"label": "C", "text": "Bond"}, {"label": "D", "text": "Rent."}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0043', 'math', 2023, 'objective', 'The two essential factors of production in the Cobb-Douglas production formula are', '[{"label": "A", "text": "Land and Entrepreneurship."}, {"label": "B", "text": "Land and Labour"}, {"label": "C", "text": "Capital and Labour"}, {"label": "D", "text": "Capital and Land."}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0044', 'math', 2023, 'objective', 'Which of these relations best describe the total cost of production?', '[{"label": "A", "text": "The sum of marginal cost and variable cost."}, {"label": "B", "text": "The sum of total variable cost and marginal cost."}, {"label": "C", "text": "The sum of marginal revenue and total fixed cost."}, {"label": "D", "text": "The sum of total variable cost and total fixed cost."}]'::jsonb, 'D', 'medium', 0, false),('mat-2023-mq-0045', 'math', 2023, 'objective', 'Which of the following best describe elasticity (e) of demand', '[{"label": "A", "text": "e = (rate of change of demand)/(rate of change of price)"}, {"label": "B", "text": "e = (rate of change of price)/(rate of change of demand)"}, {"label": "C", "text": "e = 1 \u2013 (rate of change of demand)/(rate of change of price)"}, {"label": "D", "text": "e = 1 + (rate of change of price)/(rate of change of demand)"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0046', 'math', 2023, 'objective', 'Calculate the first payment made by Mr. Iyanda after borrowing N1000 yearly instalment and repays N50 at 8% per annum.', '[{"label": "A", "text": "N64.92"}, {"label": "B", "text": "N46.29"}, {"label": "C", "text": "N96.24"}, {"label": "D", "text": "N42.96"}]'::jsonb, 'B', 'medium', 0, false),('mat-2023-mq-0047', 'math', 2023, 'objective', 'The production function of a company is given Q = 2x½y⅔. Find the marginal productivity of labour', '[{"label": "A", "text": "2x\u207b\u00bdy\u2154"}, {"label": "B", "text": "4x\u00bdy\u2154"}, {"label": "C", "text": "3x\u00bdy\u2154"}, {"label": "D", "text": "x\u2154y\u2154"}]'::jsonb, 'A', 'medium', 0, false),('mat-2023-mq-0048', 'math', 2023, 'objective', 'The consumption function for a commodity is C = 200 + 0.25I. What is the Marginal Propensity to Save?', '[{"label": "A", "text": "0.25"}, {"label": "B", "text": "0.45"}, {"label": "C", "text": "0.55"}, {"label": "D", "text": "0.75"}]'::jsonb, 'D', 'medium', 0, false),('mat-2023-mq-0049', 'math', 2023, 'objective', 'Which of the following gives the revenue of a company?', '[{"label": "A", "text": "Product of selling price and units bought."}, {"label": "B", "text": "Product of units sold and quantity bought."}, {"label": "C", "text": "Product of selling price and units sold."}, {"label": "D", "text": "Product of buying price and units sold."}]'::jsonb, 'C', 'medium', 0, false),('mat-2023-mq-0050', 'math', 2023, 'objective', 'Consider the linear programming problem Z=15x+10y subject to 2x+3y≤15, 5x+7y≤30. The inequalities in equation (2) are called', '[{"label": "A", "text": "objective functions."}, {"label": "B", "text": "Constrains"}, {"label": "C", "text": "Feasible solutions."}, {"label": "D", "text": "Optimal values"}]'::jsonb, 'B', 'medium', 0, false);